// Each villager remembers the player's actual choice, including its harm.
export function endingMemories(choices,name){
 const [forest,water,farm,festival]=choices;
 const memories=[
  ['숲지기',{
   cut:'처음 숲길을 함께 걸었던 날이 생각나. 이제 그 길에서 토끼를 다시 볼 수 없다는 게 마음 아파. 다음에는 동물의 길도 먼저 살펴보자.',
   detour:'함께 조금 먼 길을 걸었던 봄이 기억나. 덕분에 토끼가 살던 숲이 남았어. 그 길을 같이 걸어 줘서 고마워.',
   corridor:'흙에 남은 작은 발자국을 함께 찾았지? 동물이 건널 곳을 살펴 줘서 고마워. 다음 봄에도 통로를 점검할게.',
   garden:'함께 꽃밭을 만들던 봄이 생각나. 예쁜 꽃만 보고 새의 집은 놓쳤어. 다음에는 덤불 속 생물도 함께 살펴보자.'
  }[forest]],
  ['물지기',{
   treat:'여름에 하천을 살피던 우리 모습이 기억나. 더러운 물이 들어오는 곳을 고치는 일에 함께해 줘서 고마워. 앞으로도 물을 검사할게.',
   clean:'여름에 물가의 쓰레기를 건지던 날을 기억해. 함께 치워 준 건 고마워. 하지만 관에서 흘러드는 더러운 물도 꼭 줄여야 해.',
   hide:'물가에 가림막을 세웠던 날이 생각나. 뒤에서 계속 흐르던 더러운 물을 외면했지. 다음에는 물속 생물의 처지도 생각하자.',
   share:'동전을 세 주머니에 나누던 여름이 생각나. 다 해 보려 했지만 시설 수리를 끝내지 못했어. 다음에는 원인을 줄이는 일부터 끝내자.'
  }[water]],
  ['밭지기',{
   care:'가을에 잎을 하나씩 살피던 날이 기억나. 작물과 작은 생물을 함께 생각해 줘서 고마워. 다음 계절에도 필요한 곳만 관리할게.',
   spray:'밭에 농약을 많이 뿌리던 날이 생각나. 흙과 물에 남은 약이 작은 생물까지 해쳤어. 빨리 해결하려다 놓친 것을 잊지 말자.',
   garden:'한 종류의 꽃으로 밭을 채웠던 가을이 기억나. 여러 풀과 작은 생물이 살던 자리를 지우고 말았어. 다음에는 함께 살 곳을 남기자.',
   wait:'네가 찍어 둔 가을 사진을 다시 봤어. 그때 피해를 살펴보고 관리했더라면 좋았을 텐데. 사진 속 작물과 못 거둔 수확을 기억할게.'
  }[farm]],
  ['빛지기',{
   reuse:'겨울에 컵을 돌려받고 조명을 끄던 모습이 기억나. 축제 뒤까지 생각해 줘서 고마워. 다음 행사에서도 함께 이어 가자.',
   once:'축제가 끝난 뒤 함께 광장을 쓸던 날을 기억해. 치워 준 건 고마워. 다음에는 처음부터 쓰레기를 적게 만들 방법도 찾아보자.',
   party:'종이컵을 쌓고 전구를 살피던 겨울이 생각나. 반짝이는 순간 뒤에 남을 쓰레기는 놓쳤어. 다음 축제는 준비할 때부터 바꿔 보자.',
   burn:'겨울 광장을 덮었던 연기가 아직 기억나. 쓰레기는 사라져도 나빠진 공기는 우리 곁에 남았어. 다음에는 태우지 않고 처리하자.'
  }[festival]]
 ];
 return memories.map(([speaker,text])=>({speaker,text:`${name}, ${text}`}));
}
